skip_unless_full_tests()

# Expected values are SymPy's outputs for the calls of
# sympy/assumptions/tests, printed as SymPy prints them.

ns <- asNamespace("symcompR")
.fmt <- function(v) {
  if (is.null(v)) return("None")
  if (isTRUE(attr(v, "pydict")))
    return(paste0("{", paste(sort(vapply(v, function(kv) paste0(.fmt(kv[[1]]), ": ", .fmt(kv[[2]])), ""),
                                  method = "radix"), collapse = ", "), "}"))
  if (isTRUE(attr(v, "pytuple")))
    return(paste0("(", paste(vapply(v, .fmt, ""), collapse = ", "), if (length(v) == 1L) ",", ")"))
  if (isTRUE(attr(v, "pyset")))
    return(paste0("{", paste(sort(vapply(v, .fmt, ""), method = "radix"), collapse = ", "), "}"))
  if (inherits(v, "sym") || inherits(v, "symmatrix")) return(sstr(v))
  if (is.function(v) && !is.null(attr(v, "predicate"))) return(sstr(attr(v, "predicate")))
  if (is.character(v) && length(v) == 1L) return(paste0("'", v, "'"))
  if (is.logical(v) && length(v) == 1L) return(if (is.na(v)) "None" else if (v) "True" else "False")
  if (is.numeric(v) && length(v) == 1L) return(format(v))
  if (is.list(v) && !is.object(v)) return(paste0("[", paste(vapply(v, .fmt, ""), collapse = ", "), "]"))
  paste(format(v), collapse = " ")
}
.err_class <- function(e) {
  cl <- setdiff(class(e), c("simpleError", "error", "condition", "sympy_error"))
  if (length(cl)) cl[1L] else "Error"
}
# each case runs in its own environment, as in the battery runner
.res <- function(expr) {
  global_assumptions$clear()
  v <- tryCatch(gsub("**", "^", .fmt(suppressWarnings(expr)), fixed = TRUE),
                error = function(e) paste0("ERR ", .err_class(e), ": ", conditionMessage(e)))
  gsub("\n", "\\n", v, fixed = TRUE)
}
py_in <- function(a, b) {
  if (inherits(b, "AssumptionsContext")) return(get(".ctx_contains", ns)(b, a))
  any(vapply(b, function(w) identical(as_sym(w)$key, as_sym(a)$key), TRUE))
}
py_eq <- function(a, b) {
  if (inherits(a, "sym") && inherits(b, "sym")) return(identical(a$key, b$key))
  identical(.fmt(a), .fmt(b))
}
py_set <- function(...) structure(list(...), pyset = TRUE)
# SymPy module level names of internal functions
for (nm in c(".ask_recursive", ".ask_single_fact", ".CNF_from_prop", ".CNF_to_CNF", ".cnf_add_clauses"))
  assign(nm, get(nm, ns))
for (nm in c("allargs", "anyarg", "exactlyonearg", "extract_predargs", "get_relevant_clsfacts",
             "generate_known_facts_dict", "class_fact_registry", "refine_sin_cos", "CNF", "Literal"))
  assign(nm, get(paste0(".", nm), ns))
get_all_known_facts <- function() get(".get_all_known_facts", ns)()$clauses
