  expect_equal(.res(local({x <- sym_symbols("x", real = TRUE); x <- sym_symbols("x", imaginary = TRUE); x <- sym_symbols("x", complex = TRUE); x <- sym_symbols("x", positive = TRUE); x <- sym_symbols("x", commutative = FALSE); x <- sym_symbols("x", negative = TRUE); x <- sym_symbols("x", nonnegative = TRUE); x <- sym_symbols("x", finite = TRUE); x <- sym_symbols("x", prime = TRUE); x <- sym_symbols("x", composite = TRUE); x <- sym_symbols("x", even = TRUE); x <- sym_symbols("x", odd = TRUE); x <- sym_symbols("x", nonzero = TRUE); x <- sym_symbols("x", zero = TRUE); x <- sym_symbols("x", integer = TRUE); x <- sym_symbols("x", rational = TRUE); x <- sym_symbols("x", irrational = TRUE); x <- sym_symbols("x", transcendental = TRUE); .ask_recursive(Q$transcendental(x))})), "True")
