  expect_equal(.res(local({.ask_recursive(Q$zero(x), (Q$negative(x) | Q$positive(x)))})), "None")
  expect_equal(.res(local({.ask_recursive(Q$zero(x), (Q$nonnegative(x) & Q$nonpositive(x)))})), "None")
  expect_equal(.res(local({.ask_recursive((Q$zero(x) | Q$zero(y)), Q$zero((x * y)))})), "None")
  expect_equal(.res(local({.ask_recursive(Q$negative(x), Implies(Q$real(x), Q$positive(x)))})), "None")
  expect_equal(.res(local({.ask_recursive(Q$negative(x), Equivalent(Q$real(x), Q$positive(x)))})), "None")
  expect_equal(.res(local({.ask_recursive(Q$negative(x), Xor(Q$real(x), Q$negative(x)))})), "None")
  expect_equal(.res(local({.ask_recursive((Q$negative(x) & Q$integer(x)), assumptions = Implies(Q$real(x), Q$positive(x)))})), "None")
  expect_equal(.res(local({.ask_recursive((Q$real(x) | Q$integer(x)), (Q$real(x) | Q$integer(x)))})), "None")
  expect_equal(.res(local({.ask_recursive((Q$real(x) | (!Q$real(x))))})), "None")
  expect_equal(.res(local({.ask_recursive((Q$real(x) & (!Q$real(x))))})), "None")
  expect_equal(.res(local({.ask_recursive(Q$positive((x ^ y)), (Q$zero(x) & Q$positive(y)))})), "None")
})

test_that("test_refine matches SymPy", {
  tryCatch({w <- Symbol("w")}, error = function(e) NULL)
  tryCatch({x <- Symbol("x")}, error = function(e) NULL)
  tryCatch({y <- Symbol("y")}, error = function(e) NULL)
  tryCatch({z <- Symbol("z")}, error = function(e) NULL)
  expect_equal(.res(local({refine(Abs(x), Q$positive(x))})), "x")
  expect_equal(.res(local({refine((S(1) + Abs(x)), Q$positive(x))})), "x + 1")
  expect_equal(.res(local({refine(Abs(x), Q$negative(x))})), "-x")
  expect_equal(.res(local({refine((S(1) + Abs(x)), Q$negative(x))})), "1 - x")
  expect_equal(.res(local({refine(Abs((x ^ S(2))))})), "Abs(x^2)")
  expect_equal(.res(local({refine(Abs((x ^ S(2))), Q$real(x))})), "x^2")
  expect_equal(.res(local({refine((Abs(z) ^ S(2)), Q$real(z))})), "z^2")
  expect_equal(.res(local({refine((Abs(z) ^ S(2)), Q$imaginary(z))})), "-z^2")
  expect_equal(.res(local({refine((Abs(z) ^ S(4)), Q$imaginary(z))})), "z^4")
  expect_equal(.res(local({refine((Abs(z) ^ S(6)), Q$imaginary(z))})), "-z^6")
  expect_equal(.res(local({refine((S(-1) ^ x), Q$even(x))})), "1")
  expect_equal(.res(local({refine((S(-1) ^ x), Q$odd(x))})), "-1")
  expect_equal(.res(local({refine((S(-2) ^ x), Q$even(x))})), "2^x")
  expect_equal(.res(local({refine(sqrt((x ^ S(2))))})), "sqrt(x^2)")
  expect_equal(.res(local({refine(sqrt((x ^ S(2))), Q$complex(x))})), "sqrt(x^2)")
  expect_equal(.res(local({refine(sqrt((x ^ S(2))), Q$real(x))})), "Abs(x)")
  expect_equal(.res(local({refine(sqrt((x ^ S(2))), Q$positive(x))})), "x")
  expect_equal(.res(local({refine(((x ^ S(3)) ^ Rational(1, 3)))})), "(x^3)^(1/3)")
  expect_equal(.res(local({refine(((x ^ S(3)) ^ Rational(1, 3)), Q$real(x))})), "Abs(x)")
  expect_equal(.res(local({refine(((x ^ S(3)) ^ Rational(1, 3)), Q$positive(x))})), "x")
  expect_equal(.res(local({refine(sqrt((S(1) / x)), Q$real(x))})), "sqrt(1/x)")
  expect_equal(.res(local({refine(sqrt((S(1) / x)), Q$positive(x))})), "1/sqrt(x)")
  expect_equal(.res(local({refine((S(-1) ^ (x + y)), Q$even(x))})), "(-1)^y")
  expect_equal(.res(local({refine((S(-1) ^ ((x + y) + z)), (Q$odd(x) & Q$odd(z)))})), "(-1)^y")
  expect_equal(.res(local({refine((S(-1) ^ ((x + y) + S(1))), Q$odd(x))})), "(-1)^y")
  expect_equal(.res(local({refine((S(-1) ^ ((x + y) + S(2))), Q$odd(x))})), "(-1)^(y + 1)")
  expect_equal(.res(local({refine((S(-1) ^ (x + S(3))))})), "(-1)^(x + 1)")
  expect_equal(.res(local({refine((S(-1) ^ (((S(-1) ^ x) / S(2)) - S_Half)), Q$integer(x))})), "(-1)^x")
  expect_equal(.res(local({refine((S(-1) ^ (((S(-1) ^ x) / S(2)) + S_Half)), Q$integer(x))})), "(-1)^(x + 1)")
  expect_equal(.res(local({refine((S(-1) ^ (((S(-1) ^ x) / S(2)) + (S(5) * S_Half))), Q$integer(x))})), "(-1)^(x + 1)")
  expect_equal(.res(local({refine((S(-1) ^ (((S(-1) ^ x) / S(2)) - (S(7) * S_Half))), Q$integer(x))})), "(-1)^(x + 1)")
  expect_equal(.res(local({refine((S(-1) ^ (((S(-1) ^ x) / S(2)) - (S(9) * S_Half))), Q$integer(x))})), "(-1)^x")
  expect_equal(.res(local({refine((Abs(x) ^ S(2)), Q$real(x))})), "x^2")
  expect_equal(.res(local({refine((Abs(x) ^ S(3)), Q$real(x))})), "Abs(x)^3")
  expect_equal(.res(local({refine((Abs(x) ^ S(2)))})), "Abs(x)^2")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); refine(exp((((sym_pi * sym_I) * S(2)) * x)))})), "1")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); refine(exp((((sym_pi * sym_I) * S(2)) * (x + S_Half))))})), "-1")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); refine(exp((((sym_pi * sym_I) * S(2)) * (x + Rational(1, 4)))))})), "I")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); refine(exp((((sym_pi * sym_I) * S(2)) * (x + Rational(3, 4)))))})), "-I")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); x <- Symbol("x"); refine(exp((((sym_pi * sym_I) * S(2)) * x)), Q$integer(x))})), "1")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); x <- Symbol("x"); refine(exp(((sym_pi * sym_I) * x)), Q$even(x))})), "1")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); x <- Symbol("x"); refine(exp((((sym_pi * sym_I) * S(2)) * (x + S_Half))), Q$integer(x))})), "-1")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); x <- Symbol("x"); refine(exp(((sym_pi * sym_I) * x)), Q$odd(x))})), "-1")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); x <- Symbol("x"); refine(exp((((sym_pi * sym_I) * S(2)) * (x + Rational(1, 4)))), Q$integer(x))})), "I")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); x <- Symbol("x"); refine(exp((((sym_pi * sym_I) * S(2)) * (x + Rational(3, 4)))), Q$integer(x))})), "-I")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); x <- Symbol("x"); refine(exp(((sym_pi * sym_I) * (x + Rational(1, 2)))), Q$even(x))})), "I")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); x <- Symbol("x"); refine(exp(((sym_pi * sym_I) * (x + Rational(1, 2)))), Q$odd(x))})), "-I")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); x <- Symbol("x"); refine(exp(((sym_pi * sym_I) * (x + Rational(3, 2)))), Q$odd(x))})), "I")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); x <- Symbol("x"); refine(exp(((sym_pi * sym_I) * (x + Rational(1, 2)))), Q$integer(x))})), "(-1)^x*I")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); x <- Symbol("x"); refine(exp((((S(2) * sym_pi) * sym_I) * ((x + y) + Rational(1, 4)))), (Q$integer(x) & Q$integer(y)))})), "I")
  expect_equal(.res(local({x <- Symbol("x", integer = TRUE); x <- Symbol("x"); refine(exp(((sym_pi * sym_I) * x)), Q$integer(x))})), "(-1)^x")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x < S(0))), list(S(3), TRUE)), (x < S(0)))})), "1")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x < S(0))), list(S(3), TRUE)), (!(x < S(0))))})), "3")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x < S(0))), list(S(3), TRUE)), (y < S(0)))})), "Piecewise((1, x < 0), (3, True))")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x > S(0))), list(S(3), TRUE)), (x > S(0)))})), "1")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x > S(0))), list(S(3), TRUE)), (!(x > S(0))))})), "3")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x > S(0))), list(S(3), TRUE)), (y > S(0)))})), "Piecewise((1, x > 0), (3, True))")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x <= S(0))), list(S(3), TRUE)), (x <= S(0)))})), "1")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x <= S(0))), list(S(3), TRUE)), (!(x <= S(0))))})), "3")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x <= S(0))), list(S(3), TRUE)), (y <= S(0)))})), "Piecewise((1, x <= 0), (3, True))")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x >= S(0))), list(S(3), TRUE)), (x >= S(0)))})), "1")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x >= S(0))), list(S(3), TRUE)), (!(x >= S(0))))})), "3")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x >= S(0))), list(S(3), TRUE)), (y >= S(0)))})), "Piecewise((1, x >= 0), (3, True))")
  expect_equal(.res(local({refine(Piecewise(list(S(1), Eq(x, S(0))), list(S(3), TRUE)), Eq(x, S(0)))})), "1")
  expect_equal(.res(local({refine(Piecewise(list(S(1), Eq(x, S(0))), list(S(3), TRUE)), Eq(S(0), x))})), "1")
  expect_equal(.res(local({refine(Piecewise(list(S(1), Eq(x, S(0))), list(S(3), TRUE)), (!Eq(x, S(0))))})), "3")
  expect_equal(.res(local({refine(Piecewise(list(S(1), Eq(x, S(0))), list(S(3), TRUE)), (!Eq(S(0), x)))})), "3")
  expect_equal(.res(local({refine(Piecewise(list(S(1), Eq(x, S(0))), list(S(3), TRUE)), Eq(y, S(0)))})), "Piecewise((1, Eq(x, 0)), (3, True))")
  expect_equal(.res(local({refine(Piecewise(list(S(1), Ne(x, S(0))), list(S(3), TRUE)), Ne(x, S(0)))})), "1")
  expect_equal(.res(local({refine(Piecewise(list(S(1), Ne(x, S(0))), list(S(3), TRUE)), (!Ne(x, S(0))))})), "3")
  expect_equal(.res(local({refine(Piecewise(list(S(1), Ne(x, S(0))), list(S(3), TRUE)), Ne(y, S(0)))})), "Piecewise((1, Ne(x, 0)), (3, True))")
  expect_equal(.res(local({refine(sym_atan2(y, x), (Q$real(y) & Q$positive(x)))})), "atan(y/x)")
