  expect_equal(.res(local({refine(sym_atan2(y, x), (Q$zero(y) & Q$negative(x)))})), "pi")
  expect_equal(.res(local({refine(sym_atan2(y, x), (Q$positive(y) & Q$zero(x)))})), "pi/2")
