  expect_equal(.res(local({refine(im((x * y)), (Q$imaginary(x) & Q$imaginary(y)))})), "0")
  expect_equal(.res(local({refine(im((S(1) / x)), Q$imaginary(x))})), "-I/x")
  expect_equal(.res(local({refine(im(((x * y) * z)), ((Q$imaginary(x) & Q$imaginary(y)) & Q$imaginary(z)))})), "-I*x*y*z")
  expect_equal(.res(local({refine(re((S(1) / (x + (sym_I * y)))), (Q$real(x) & Q$real(y)))})), "x/(x^2 + y^2)")
  expect_equal(.res(local({refine(im((S(1) / (x + (sym_I * y)))), (Q$real(x) & Q$real(y)))})), "-y/(x^2 + y^2)")
  expect_equal(.res(local({refine(re(((w + (sym_I * x)) * (y + (sym_I * z)))), (((Q$real(w) & Q$real(x)) & Q$real(y)) & Q$real(z)))})), "w*y - x*z")
  expect_equal(.res(local({refine(im(((w + (sym_I * x)) * (y + (sym_I * z)))), (((Q$real(w) & Q$real(x)) & Q$real(y)) & Q$real(z)))})), "w*z + x*y")
  expect_equal(.res(local({x <- Symbol("x", real = TRUE); refine(sign(x), Q$positive(x))})), "1")
  expect_equal(.res(local({x <- Symbol("x", real = TRUE); refine(sign(x), Q$negative(x))})), "-1")
  expect_equal(.res(local({x <- Symbol("x", real = TRUE); refine(sign(x), Q$zero(x))})), "0")
  expect_equal(.res(local({x <- Symbol("x", real = TRUE); refine(sign(x), TRUE)})), "sign(x)")
  expect_equal(.res(local({x <- Symbol("x", real = TRUE); refine(sign(Abs(x)), Q$nonzero(x))})), "1")
  expect_equal(.res(local({x <- Symbol("x", real = TRUE); x <- Symbol("x", imaginary = TRUE); refine(sign(x), Q$positive(im(x)))})), "I")
  expect_equal(.res(local({x <- Symbol("x", real = TRUE); x <- Symbol("x", imaginary = TRUE); refine(sign(x), Q$negative(im(x)))})), "-I")
  expect_equal(.res(local({x <- Symbol("x", real = TRUE); x <- Symbol("x", imaginary = TRUE); refine(sign(x), TRUE)})), "sign(x)")
  expect_equal(.res(local({x <- Symbol("x", real = TRUE); x <- Symbol("x", imaginary = TRUE); x <- Symbol("x", complex = TRUE); refine(sign(x), Q$zero(x))})), "0")
  expect_equal(.res(local({x <- Symbol("x", complex = TRUE); refine(arg(x), Q$positive(x))})), "0")
  expect_equal(.res(local({x <- Symbol("x", complex = TRUE); refine(arg(x), Q$negative(x))})), "pi")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x < S(0))), list(S(0), TRUE)), Q$positive(x))})), "0")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x < S(0))), list(S(0), TRUE)), Q$negative(x))})), "1")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x > S(0))), list(S(0), TRUE)), Q$positive(x))})), "1")
  expect_equal(.res(local({refine(Piecewise(list(S(1), (x > S(0))), list(S(0), TRUE)), Q$negative(x))})), "0")
  expect_equal(.res(local({expr1 <- refine(Abs((x * y)), Q$positive(x)); expr2 <- refine(Abs(((x * y) * z)), Q$positive(x)); expr1})), "x*Abs(y)")
  expect_equal(.res(local({expr1 <- refine(Abs((x * y)), Q$positive(x)); expr2 <- refine(Abs(((x * y) * z)), Q$positive(x)); expr2})), "x*Abs(y*z)")
  expect_equal(.res(local({expr1 <- refine(Abs((x * y)), Q$positive(x)); expr2 <- refine(Abs(((x * y) * z)), Q$positive(x)); y1 <- Symbol("y1", real = TRUE); expr3 <- refine(Abs(((x * (y1 ^ S(2))) * z)), Q$positive(x)); expr3})), "x*y1^2*Abs(z)")
  expect_equal(.res(local({x <- MatrixSymbol("x", 3, 3); i <- Symbol("i", positive = TRUE); j <- Symbol("j", positive = TRUE); refine(MatrixElement(x, 0, 1), Q$symmetric(x))})), "x[0, 1]")
  expect_equal(.res(local({x <- MatrixSymbol("x", 3, 3); i <- Symbol("i", positive = TRUE); j <- Symbol("j", positive = TRUE); refine(MatrixElement(x, 1, 0), Q$symmetric(x))})), "x[0, 1]")
  expect_equal(.res(local({x <- MatrixSymbol("x", 3, 3); i <- Symbol("i", positive = TRUE); j <- Symbol("j", positive = TRUE); refine(MatrixElement(x, i, j), Q$symmetric(x))})), "x[j, i]")
  expect_equal(.res(local({x <- MatrixSymbol("x", 3, 3); i <- Symbol("i", positive = TRUE); j <- Symbol("j", positive = TRUE); refine(MatrixElement(x, j, i), Q$symmetric(x))})), "x[j, i]")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos(((n * sym_pi) / S(2))), Q$odd(n))})), "0")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos((n * sym_pi)), Q$even(n))})), "1")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos((n * sym_pi)), Q$odd(n))})), "-1")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin((n * sym_pi)), Q$integer(n))})), "0")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin(((n * sym_pi) / S(2))), (Q$odd(n) & Q$even(((n - S(1)) / S(2)))))})), "1")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin(((n * sym_pi) / S(2))), (Q$odd(n) & Q$odd(((n - S(1)) / S(2)))))})), "-1")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos((n * sym_pi)), Q$integer(n))})), "(-1)^n")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin(((n * sym_pi) / S(2))), Q$even(n))})), "0")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos(((n * sym_pi) / S(2))), Q$even(n))})), "(-1)^(n/2)")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin(((n * sym_pi) / S(2))), Q$odd(n))})), "(-1)^(n/2 + 3/2)")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos(((n * sym_pi) / S(2))), Q$odd(n))})), "0")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin((x + (n * sym_pi))), Q$integer(n))})), "(-1)^n*sin(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos((x + (n * sym_pi))), Q$integer(n))})), "(-1)^n*cos(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin((x + (n * sym_pi))), Q$even(n))})), "sin(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos((x + (n * sym_pi))), Q$even(n))})), "cos(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin((x + (n * sym_pi))), Q$odd(n))})), "-sin(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos((x + (n * sym_pi))), Q$odd(n))})), "-cos(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin((x - (n * sym_pi))), Q$odd(n))})), "-sin(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos((x - (n * sym_pi))), Q$even(n))})), "cos(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin((x + ((n * sym_pi) / S(2)))), Q$even(n))})), "(-1)^(n/2)*sin(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos((x + ((n * sym_pi) / S(2)))), Q$even(n))})), "(-1)^(n/2)*cos(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin((x + ((n * sym_pi) / S(2)))), Q$odd(n))})), "(-1)^(n/2 + 3/2)*cos(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos((x + ((n * sym_pi) / S(2)))), Q$odd(n))})), "(-1)^(n/2 + 1/2)*sin(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin((x - ((n * sym_pi) / S(2)))), Q$odd(n))})), "-(-1)^(n/2 + 3/2)*cos(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos((x - ((n * sym_pi) / S(2)))), Q$even(n))})), "(-1)^(n/2)*cos(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin(((x + y) + ((S(2) * n) * sym_pi))), Q$integer(n))})), "sin(x + y)")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos(((x + y) + ((S(2) * n) * sym_pi))), Q$integer(n))})), "cos(x + y)")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin((x + (n * sym_pi))), Q$zero(n))})), "sin(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(sin((x + (n * sym_pi))), Q$zero((-n)))})), "sin(x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos((x + ((n * sym_pi) / S(2)))), Q$integer(n))})), "cos(pi*n/2 + x)")
  expect_equal(.res(local({n <- Symbol("n"); refine(cos(((x + y) + ((n * sym_pi) / S(2)))), Q$integer(n))})), "cos(pi*n/2 + x + y)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); refine(cos(((x + (n * sym_pi)) + ((m * sym_pi) / S(2)))), (Q$integer(n) & Q$even(m)))})), "(-1)^(m/2 + n)*cos(x)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); refine(cos(((x + (n * sym_pi)) + ((m * sym_pi) / S(2)))), (Q$integer(n) & Q$odd(m)))})), "(-1)^(m/2 + n + 1/2)*sin(x)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); refine(cos(((x + (n * sym_pi)) + ((m * sym_pi) / S(2)))), (Q$integer(n) & Q$integer(m)))})), "(-1)^n*cos(pi*m/2 + x)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); refine(cos(((x + (((S(2) * n) + S(1)) * sym_pi)) + ((m * sym_pi) / S(2)))), (Q$integer(n) & Q$integer(m)))})), "-cos(pi*m/2 + x)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); refine(sin(((x - ((S(2) * n) * sym_pi)) + ((m * sym_pi) / S(2)))), (Q$integer(n) & Q$integer(m)))})), "sin(pi*m/2 + x)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); k <- Symbol("k"); refine(cos((((x + (n * sym_pi)) + ((k * sym_pi) / S(2))) + ((m * sym_pi) / S(2)))), ((Q$integer(n) & Q$odd(k)) & Q$integer(m)))})), "(-1)^(k/2 + n + 1/2)*sin(pi*m/2 + x)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); k <- Symbol("k"); refine(sin((((x + (n * sym_pi)) + ((k * sym_pi) / S(2))) + ((m * sym_pi) / S(2)))), ((Q$integer(n) & Q$odd(k)) & Q$integer(m)))})), "(-1)^(k/2 + n + 3/2)*cos(pi*m/2 + x)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); k <- Symbol("k"); refine(cos((((x + ((n * sym_pi) / S(2))) + ((k * sym_pi) / S(2))) + ((m * sym_pi) / S(2)))), ((Q$odd(n) & Q$odd(k)) & Q$integer(m)))})), "(-1)^(k/2 + n/2)*cos(pi*m/2 + x)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); k <- Symbol("k"); refine(cos(x), Q$zero(x))})), "1")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); k <- Symbol("k"); refine(sin(x), Q$zero(x))})), "0")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); k <- Symbol("k"); refine(sin(x), (Q$infinite(x) & Q$extended_real(x)))})), "AccumBounds(-1, 1)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); k <- Symbol("k"); refine(cos(x), (Q$infinite(x) & Q$extended_real(x)))})), "AccumBounds(-1, 1)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); k <- Symbol("k"); refine(sin(x), Q$infinite(x))})), "sin(x)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); k <- Symbol("k"); refine(cos(x), Q$infinite(x))})), "cos(x)")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); k <- Symbol("k"); refine_sin_cos(tan(x), Q$real(x))})), "ERR TypeError: refine_sin_cos expects a sin or cos function.")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); k <- Symbol("k"); refine_sin_cos(exp(x), Q$real(x))})), "ERR TypeError: refine_sin_cos expects a sin or cos function.")
  expect_equal(.res(local({n <- Symbol("n"); m <- Symbol("m"); k <- Symbol("k"); refine_sin_cos(x, Q$real(x))})), "ERR TypeError: refine_sin_cos expects a sin or cos function.")
  expect_equal(.res(local({refine(floor(x), Q$integer(x))})), "x")
  expect_equal(.res(local({refine(ceiling(x), Q$integer(x))})), "x")
  expect_equal(.res(local({refine(floor(x), Q$infinite(x))})), "x")
  expect_equal(.res(local({refine(ceiling(x), Q$infinite(x))})), "x")
  expect_equal(.res(local({refine(floor(y), Q$real(y))})), "floor(y)")
  expect_equal(.res(local({refine(ceiling(y), Q$real(y))})), "ceiling(y)")
  expect_equal(.res(local({refine(floor((x + y)), Q$integer(x))})), "x + floor(y)")
  expect_equal(.res(local({refine(ceiling((x + y)), Q$integer(x))})), "x + ceiling(y)")
  expect_equal(.res(local({refine(floor(((x + y) + z)), (Q$integer(x) & Q$integer(y)))})), "x + y + floor(z)")
  expect_equal(.res(local({refine(ceiling(((x + y) + z)), (Q$integer(x) & Q$integer(z)))})), "x + z + ceiling(y)")
  expect_equal(.res(local({refine(floor(((x + y) - z)))})), "floor(x + y - z)")
  expect_equal(.res(local({refine(ceiling(((ceiling(x) + y) + floor(z))))})), "ceiling(x) + ceiling(y) + floor(z)")
  expect_equal(.res(local({refine(floor((floor(x) + floor(y))))})), "floor(x) + floor(y)")
  expect_equal(.res(local({refine(Heaviside(x), Q$positive(x))})), "1")
  expect_equal(.res(local({refine(Heaviside(x), Q$negative(x))})), "0")
  expect_equal(.res(local({refine(Heaviside(x), Q$zero(x))})), "1/2")
  expect_equal(.res(local({refine(Heaviside(x), Q$nonnegative(x))})), "Heaviside(x)")
  expect_equal(.res(local({refine(Heaviside(x), Q$nonpositive(x))})), "Heaviside(x)")
  expect_equal(.res(local({refine(Heaviside(x), TRUE)})), "Heaviside(x)")
  expect_equal(.res(local({refine(Heaviside(x, S(1)), Q$zero(x))})), "1")
  expect_equal(.res(local({refine(Heaviside(x, S(1)), Q$positive(x))})), "1")
  expect_equal(.res(local({refine(Heaviside(x, S(1)), Q$negative(x))})), "0")
})

test_that("test_matrices matches SymPy", {
  tryCatch({X <- MatrixSymbol("X", 2, 2)}, error = function(e) NULL)
  tryCatch({Y <- MatrixSymbol("Y", 2, 3)}, error = function(e) NULL)
  tryCatch({Z <- MatrixSymbol("Z", 2, 2)}, error = function(e) NULL)
  tryCatch({A1x1 <- MatrixSymbol("A1x1", 1, 1)}, error = function(e) NULL)
  tryCatch({B1x1 <- MatrixSymbol("B1x1", 1, 1)}, error = function(e) NULL)
  tryCatch({C0x0 <- MatrixSymbol("C0x0", 0, 0)}, error = function(e) NULL)
  tryCatch({V1 <- MatrixSymbol("V1", 2, 1)}, error = function(e) NULL)
  tryCatch({V2 <- MatrixSymbol("V2", 2, 1)}, error = function(e) NULL)
  expect_equal(.res(local({.ask_recursive(Q$square(X))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$square(Y))})), "False")
  expect_equal(.res(local({.ask_recursive(Q$square((Y * t(Y))))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$invertible(X), Q$invertible(X))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$invertible(Y))})), "False")
  expect_equal(.res(local({.ask_recursive(Q$invertible((X * Y)), Q$invertible(X))})), "False")
  expect_equal(.res(local({.ask_recursive(Q$invertible((X * Z)), Q$invertible(X))})), "None")
  expect_equal(.res(local({.ask_recursive(Q$invertible((X * Z)), (Q$invertible(X) & Q$invertible(Z)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$invertible(t(X)))})), "None")
  expect_equal(.res(local({.ask_recursive(Q$invertible(t(X)), Q$invertible(X))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$invertible((X)^-1))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$invertible(Identity(3)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$invertible(ZeroMatrix(3, 3)))})), "False")
  expect_equal(.res(local({.ask_recursive(Q$invertible(OneMatrix(1, 1)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$invertible(OneMatrix(3, 3)))})), "False")
  expect_equal(.res(local({ask(Q$invertible(X), (Q$fullrank(X) & Q$square(X)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$singular(X))})), "None")
  expect_equal(.res(local({.ask_recursive(Q$singular(X), Q$invertible(X))})), "False")
  expect_equal(.res(local({ask(Q$singular(X), (!Q$invertible(X)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$invertible(X), Q$fullrank(X))})), "None")
  expect_equal(.res(local({.ask_recursive(Q$invertible(BlockMatrix(list(Identity(3)))))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$invertible(BlockMatrix(list(ZeroMatrix(3, 3)))))})), "False")
  expect_equal(.res(local({X <- Matrix(list(list(1, 2, 3), list(3, 5, 4))); Y <- Matrix(list(list(4, 2, 7), list(2, 3, 5))); .ask_recursive(Q$invertible(BlockMatrix(list(list(ones(3, 3), t(Y)), list(X, eye(2))))))})), "True")
  expect_equal(.res(local({X <- Matrix(list(list(1, 2, 3), list(3, 5, 4))); Y <- Matrix(list(list(4, 2, 7), list(2, 3, 5))); .ask_recursive(Q$invertible(BlockMatrix(list(list(t(Y), ones(3, 3)), list(eye(2), X)))))})), "True")
  expect_equal(.res(local({X <- Matrix(list(list(1, 2, 3), list(3, 5, 4))); Y <- Matrix(list(list(4, 2, 7), list(2, 3, 5))); .ask_recursive(Q$invertible(BlockMatrix(list(list(X, eye(2)), list(ones(3, 3), t(Y))))))})), "True")
  expect_equal(.res(local({X <- Matrix(list(list(1, 2, 3), list(3, 5, 4))); Y <- Matrix(list(list(4, 2, 7), list(2, 3, 5))); .ask_recursive(Q$invertible(BlockMatrix(list(list(eye(2), X), list(t(Y), ones(3, 3))))))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$invertible(BlockDiagMatrix(Identity(3), Identity(5))))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$invertible(BlockDiagMatrix(ZeroMatrix(3, 3), Identity(5))))})), "False")
  expect_equal(.res(local({.ask_recursive(Q$invertible(BlockDiagMatrix(Identity(3), OneMatrix(5, 5))))})), "False")
  expect_equal(.res(local({.ask_recursive(Q$symmetric(X), Q$symmetric(X))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric((X * Z)), Q$symmetric(X))})), "None")
  expect_equal(.res(local({.ask_recursive(Q$symmetric((X * Z)), (Q$symmetric(X) & Q$symmetric(Z)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric((X + Z)), (Q$symmetric(X) & Q$symmetric(Z)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric(Y))})), "False")
  expect_equal(.res(local({.ask_recursive(Q$symmetric((Y * t(Y))))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric(((t(Y) * X) * Y)))})), "None")
  expect_equal(.res(local({.ask_recursive(Q$symmetric(((t(Y) * X) * Y)), Q$symmetric(X))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric((X ^ S(10))), Q$symmetric(X))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric(A1x1))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric((A1x1 + B1x1)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric((A1x1 * B1x1)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric((t(V1) * V1)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric((t(V1) * (V1 + V2))))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric(((t(V1) * (V1 + V2)) + A1x1)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric(MatrixSlice(Y, list(0, 1), list(1, 2))))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric(Identity(3)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric(ZeroMatrix(3, 3)))})), "True")
  expect_equal(.res(local({.ask_recursive(Q$symmetric(OneMatrix(3, 3)))})), "True")
  expect_equal(.res(local({predicate <- Q$orthogonal; .ask_recursive(predicate(X), predicate(X))})), "True")
  expect_equal(.res(local({predicate <- Q$orthogonal; .ask_recursive(predicate(t(X)), predicate(X))})), "True")
  expect_equal(.res(local({predicate <- Q$orthogonal; .ask_recursive(predicate((X)^-1), predicate(X))})), "True")
  expect_equal(.res(local({predicate <- Q$orthogonal; .ask_recursive(predicate((X ^ S(2))), predicate(X))})), "True")
  expect_equal(.res(local({predicate <- Q$orthogonal; .ask_recursive(predicate(Y))})), "False")
  expect_equal(.res(local({predicate <- Q$orthogonal; .ask_recursive(predicate(X))})), "None")
  expect_equal(.res(local({predicate <- Q$orthogonal; .ask_recursive(predicate(X), (!Q$invertible(X)))})), "False")
  expect_equal(.res(local({predicate <- Q$orthogonal; .ask_recursive(predicate(((X * Z) * X)), (predicate(X) & predicate(Z)))})), "True")
  expect_equal(.res(local({predicate <- Q$orthogonal; .ask_recursive(predicate(Identity(3)))})), "True")
  expect_equal(.res(local({predicate <- Q$orthogonal; .ask_recursive(predicate(ZeroMatrix(3, 3)))})), "False")
  expect_equal(.res(local({predicate <- Q$orthogonal; .ask_recursive(Q$invertible(X), predicate(X))})), "True")
  expect_equal(.res(local({predicate <- Q$orthogonal; .ask_recursive(predicate((X + Z)), (predicate(X) & predicate(Z)))})), "None")
  expect_equal(.res(local({predicate <- Q$unitary; .ask_recursive(predicate(X), predicate(X))})), "True")
  expect_equal(.res(local({predicate <- Q$unitary; .ask_recursive(predicate(t(X)), predicate(X))})), "True")
  expect_equal(.res(local({predicate <- Q$unitary; .ask_recursive(predicate((X)^-1), predicate(X))})), "True")
  expect_equal(.res(local({predicate <- Q$unitary; .ask_recursive(predicate((X ^ S(2))), predicate(X))})), "True")
  expect_equal(.res(local({predicate <- Q$unitary; .ask_recursive(predicate(Y))})), "False")
