  expect_equal(.res(local({.ask_recursive(Q$invertible(X), (Q$fullrank(X) & Q$square(X)))})), "None")
  expect_equal(.res(local({.ask_recursive(Q$singular(X), (!Q$invertible(X)))})), "None")
})

test_that("test_satask matches SymPy", {
  tryCatch({.tup <- sym_symbols("x y z"); x <- .tup[[1]]; y <- .tup[[2]]; z <- .tup[[3]]}, error = function(e) NULL)
  expect_equal(.res(local({satask(Q$real(x), Q$real(x))})), "True")
  expect_equal(.res(local({satask(Q$real(x), (!Q$real(x)))})), "False")
  expect_equal(.res(local({satask(Q$real(x))})), "None")
  expect_equal(.res(local({satask(Q$real(x), Q$positive(x))})), "True")
  expect_equal(.res(local({satask(Q$positive(x), Q$real(x))})), "None")
  expect_equal(.res(local({satask(Q$real(x), (!Q$positive(x)))})), "None")
  expect_equal(.res(local({satask(Q$positive(x), (!Q$real(x)))})), "False")
  expect_equal(.res(local({satask(Q$real(x), (Q$real(x) & (!Q$real(x))))})), "ERR ValueError: Inconsistent assumptions")
  expect_equal(.res(local({satask(Q$zero(x), Q$nonzero(x))})), "False")
  expect_equal(.res(local({satask(Q$positive(x), Q$zero(x))})), "False")
  expect_equal(.res(local({satask(Q$real(x), Q$zero(x))})), "True")
  expect_equal(.res(local({satask(Q$zero(x), Q$zero((x * y)))})), "None")
  expect_equal(.res(local({satask(Q$zero((x * y)), Q$zero(x))})), "True")
  expect_equal(.res(local({satask((Q$zero(x) | Q$zero(y)), Q$zero((x * y)))})), "True")
  expect_equal(.res(local({satask(Q$zero((x * y)), (Q$zero(x) | Q$zero(y)))})), "True")
  expect_equal(.res(local({satask(Implies(Q$zero(x), Q$zero((x * y))))})), "True")
  expect_equal(.res(local({satask((Q$zero(x) | Q$zero(y)), Q$nonzero((x * y)))})), "False")
  expect_equal(.res(local({satask(Q$zero(x), Q$zero((x ^ S(2))))})), "True")
  expect_equal(.res(local({satask(Q$zero(x), (Q$negative(x) | Q$positive(x)))})), "False")
  expect_equal(.res(local({satask(Q$zero(x), (Q$nonnegative(x) & Q$nonpositive(x)))})), "True")
  expect_equal(.res(local({satask(Q$zero((x + y)), (Q$positive(x) & Q$positive(y)))})), "False")
  expect_equal(.res(local({satask((Q$positive(x) & Q$positive(y)), Q$zero((x + y)))})), "False")
  expect_equal(.res(local({satask(Q$nonzero((x + y)), (Q$positive(x) & Q$positive(y)))})), "True")
  expect_equal(.res(local({satask((Q$positive(x) & Q$positive(y)), Q$nonzero((x + y)))})), "None")
  expect_equal(.res(local({satask(Q$zero((x * (x + y))), (Q$positive(x) & Q$positive(y)))})), "False")
  expect_equal(.res(local({satask(Q$positive((((sym_pi * x) * y) + S(1))), (Q$positive(x) & Q$positive(y)))})), "True")
  expect_equal(.res(local({satask(Q$positive((((sym_pi * x) * y) - S(5))), (Q$positive(x) & Q$positive(y)))})), "None")
  expect_equal(.res(local({satask(Q$zero((x ^ y)), (Q$zero(x) & Q$positive(y)))})), "True")
  expect_equal(.res(local({satask(Q$zero((x ^ y)), (Q$nonzero(x) & Q$zero(y)))})), "False")
  expect_equal(.res(local({satask(Q$zero(x), Q$zero((x ^ y)))})), "True")
  expect_equal(.res(local({satask(Q$zero((x ^ y)), Q$zero(x))})), "None")
  expect_equal(.res(local({A <- MatrixSymbol("A", 5, 5); B <- MatrixSymbol("B", 5, 5); satask(Q$invertible((A * B)), (Q$invertible(A) & Q$invertible(B)))})), "True")
  expect_equal(.res(local({A <- MatrixSymbol("A", 5, 5); B <- MatrixSymbol("B", 5, 5); satask(Q$invertible(A), Q$invertible((A * B)))})), "None")
  expect_equal(.res(local({A <- MatrixSymbol("A", 5, 5); B <- MatrixSymbol("B", 5, 5); satask((Q$invertible(A) & Q$invertible(B)), Q$invertible((A * B)))})), "None")
  expect_equal(.res(local({satask(Q$prime(S(5)))})), "True")
  expect_equal(.res(local({satask(Q$prime(S(6)))})), "False")
  expect_equal(.res(local({satask(Q$prime(S(-5)))})), "False")
  expect_equal(.res(local({satask(Q$prime((x * y)), (Q$integer(x) & Q$integer(y)))})), "None")
  expect_equal(.res(local({satask(Q$prime((x * y)), (Q$prime(x) & Q$prime(y)))})), "False")
  expect_equal(.res(local({satask(Q$positive(S(1)))})), "True")
  expect_equal(.res(local({satask(Q$positive(S(-1)))})), "False")
  expect_equal(.res(local({satask(Q$positive(S(0)))})), "False")
  expect_equal(.res(local({satask(Q$positive(sym_I))})), "False")
  expect_equal(.res(local({satask(Q$positive(sym_pi))})), "True")
  expect_equal(.res(local({satask(Q$negative(S(1)))})), "False")
  expect_equal(.res(local({satask(Q$negative(S(-1)))})), "True")
  expect_equal(.res(local({satask(Q$negative(S(0)))})), "False")
  expect_equal(.res(local({satask(Q$negative(sym_I))})), "False")
  expect_equal(.res(local({satask(Q$negative(sym_pi))})), "False")
  expect_equal(.res(local({satask(Q$zero(S(1)))})), "False")
  expect_equal(.res(local({satask(Q$zero(S(-1)))})), "False")
  expect_equal(.res(local({satask(Q$zero(S(0)))})), "True")
  expect_equal(.res(local({satask(Q$zero(sym_I))})), "False")
  expect_equal(.res(local({satask(Q$zero(sym_pi))})), "False")
  expect_equal(.res(local({satask(Q$nonzero(S(1)))})), "True")
  expect_equal(.res(local({satask(Q$nonzero(S(-1)))})), "True")
  expect_equal(.res(local({satask(Q$nonzero(S(0)))})), "False")
  expect_equal(.res(local({satask(Q$nonzero(sym_I))})), "False")
  expect_equal(.res(local({satask(Q$nonzero(sym_pi))})), "True")
  expect_equal(.res(local({satask(Q$nonpositive(S(1)))})), "False")
  expect_equal(.res(local({satask(Q$nonpositive(S(-1)))})), "True")
  expect_equal(.res(local({satask(Q$nonpositive(S(0)))})), "True")
  expect_equal(.res(local({satask(Q$nonpositive(sym_I))})), "False")
  expect_equal(.res(local({satask(Q$nonpositive(sym_pi))})), "False")
  expect_equal(.res(local({satask(Q$nonnegative(S(1)))})), "True")
  expect_equal(.res(local({satask(Q$nonnegative(S(-1)))})), "False")
  expect_equal(.res(local({satask(Q$nonnegative(S(0)))})), "True")
  expect_equal(.res(local({satask(Q$nonnegative(sym_I))})), "False")
  expect_equal(.res(local({satask(Q$nonnegative(sym_pi))})), "True")
