test_that("test_context matches SymPy", {
  tryCatch({x <- Symbol("x")}, error = function(e) NULL)
  tryCatch({y <- Symbol("y")}, error = function(e) NULL)
  expect_equal(.res(local({assuming(Q$integer(x), { ask(Q$integer(x)) })})), "True")
  expect_equal(.res(local({assuming(Q$integer(x), { NULL }); ask(Q$integer(x))})), "None")
  expect_equal(.res(local({ask(Q$integer(x))})), "None")
  expect_equal(.res(local({ask(Q$integer(y))})), "None")
  expect_equal(.res(local({assuming(Q$integer(x), { ask(Q$integer(x)) })})), "True")
  expect_equal(.res(local({assuming(Q$integer(x), { ask(Q$integer(y)) })})), "None")
  expect_equal(.res(local({assuming(Q$integer(x), { assuming(Q$integer(y), { ask(Q$integer(x)) }) })})), "True")
  expect_equal(.res(local({assuming(Q$integer(x), { assuming(Q$integer(y), { ask(Q$integer(y)) }) })})), "True")
  expect_equal(.res(local({assuming(Q$integer(x), { assuming(Q$integer(y), { NULL }); ask(Q$integer(x)) })})), "True")
  expect_equal(.res(local({assuming(Q$integer(x), { assuming(Q$integer(y), { NULL }); ask(Q$integer(y)) })})), "None")
  expect_equal(.res(local({assuming(Q$integer(x), { assuming(Q$integer(y), { NULL }) }); ask(Q$integer(x))})), "None")
  expect_equal(.res(local({assuming(Q$integer(x), { assuming(Q$integer(y), { NULL }) }); ask(Q$integer(y))})), "None")
  expect_equal(.res(local({tryCatch({ assuming(Q$integer(x), { (S(1) / S(0)) }) }, error = function(e) NULL); ask(Q$integer(x))})), "None")
  expect_equal(.res(local({global_assumptions$add(Q$integer(x)); assuming({ ask(Q$integer(x)) })})), "True")
  expect_equal(.res(local({global_assumptions$add(Q$integer(x)); assuming({ global_assumptions$remove(Q$integer(x)); ask(Q$integer(x)) })})), "None")
  expect_equal(.res(local({global_assumptions$add(Q$integer(x)); assuming({ global_assumptions$remove(Q$integer(x)) }); ask(Q$integer(x))})), "True")
})

test_that("test_assumptions_2 matches SymPy", {
  tryCatch({x <- Symbol("x")}, error = function(e) NULL)
  tryCatch({y <- Symbol("y")}, error = function(e) NULL)
  expect_equal(.res(local({Q$positive(x)})), "Q.positive(x)")
  expect_equal(.res(local({Q$positive(x)})), "Q.positive(x)")
  expect_equal(.res(local({(!Q$positive(x))})), "~Q.positive(x)")
  expect_equal(.res(local({pretty(Q$positive(x))})), "'Q.positive(x)'")
  expect_equal(.res(local({global_assumptions$add((x > S(0))); py_in((x > S(0)), global_assumptions)})), "True")
  expect_equal(.res(local({global_assumptions$add((x > S(0))); global_assumptions$remove((x > S(0))); py_in((x > S(0)), global_assumptions)})), "False")
  expect_equal(.res(local({global_assumptions$add((x > S(0))); global_assumptions$remove((x > S(0))); global_assumptions$add((x > S(0)), (y > S(0))); py_in((x > S(0)), global_assumptions)})), "True")
  expect_equal(.res(local({global_assumptions$add((x > S(0))); global_assumptions$remove((x > S(0))); global_assumptions$add((x > S(0)), (y > S(0))); py_in((y > S(0)), global_assumptions)})), "True")
  expect_equal(.res(local({global_assumptions$add((x > S(0))); global_assumptions$remove((x > S(0))); global_assumptions$add((x > S(0)), (y > S(0))); global_assumptions$clear(); py_in((x > S(0)), global_assumptions)})), "False")
  expect_equal(.res(local({global_assumptions$add((x > S(0))); global_assumptions$remove((x > S(0))); global_assumptions$add((x > S(0)), (y > S(0))); global_assumptions$clear(); py_in((y > S(0)), global_assumptions)})), "False")
  expect_equal(.res(local({.ask_single_fact(Q$real, CNF())})), "None")
  expect_equal(.res(local({.ask_single_fact(Q$even, .CNF_from_prop(Q$zero))})), "True")
  expect_equal(.res(local({.ask_single_fact(Q$even, .CNF_from_prop(Q$odd))})), "False")
  expect_equal(.res(local({.ask_single_fact(Q$even, .CNF_from_prop(Q$real))})), "None")
  expect_equal(.res(local({.ask_single_fact(Q$integer, .CNF_from_prop((Q$even | Q$odd)))})), "None")
  expect_equal(.res(local({.ask_single_fact(Q$integer, .CNF_from_prop(Q$prime))})), "True")
  expect_equal(.res(local({.ask_single_fact(Q$prime, .CNF_from_prop(Q$composite))})), "False")
  expect_equal(.res(local({.ask_single_fact(Q$zero, .CNF_from_prop((!Q$even)))})), "False")
  expect_equal(.res(local({.ask_single_fact(Q$zero, .CNF_from_prop(((!Q$even) & Q$real)))})), "False")
})

