  expect_equal(.res(local({.tup <- sym_symbols("a b c", real = TRUE); a <- .tup[[1]]; b <- .tup[[2]]; c <- .tup[[3]]; ask(((S(1) / a) >= (S(1) / b)), (((a <= b) & Q$positive(x)) & Q$positive(b)))})), "None")
  expect_equal(.res(local({.tup <- sym_symbols("a b c", real = TRUE); a <- .tup[[1]]; b <- .tup[[2]]; c <- .tup[[3]]; ask(((S(1) / a) >= (S(1) / b)), (((a <= b) & Q$negative(x)) & Q$negative(b)))})), "None")
