  expect_equal(.res(local({x <- Symbol("x", infinite = TRUE); y <- Symbol("y", infinite = FALSE); z <- Symbol("z"); is_infinite(y)})), "False")
  expect_equal(.res(local({x <- Symbol("x", infinite = TRUE); y <- Symbol("y", infinite = FALSE); z <- Symbol("z"); is_infinite(z)})), "None")
  expect_equal(.res(local({x <- Symbol("x", infinite = TRUE); y <- Symbol("y", infinite = FALSE); z <- Symbol("z"); is_infinite(z, Q$infinite(z))})), "True")
  expect_equal(.res(local({x <- Symbol("x", extended_real = TRUE); y <- Symbol("y", extended_real = FALSE); z <- Symbol("z"); is_extended_real(x)})), "True")
  expect_equal(.res(local({x <- Symbol("x", extended_real = TRUE); y <- Symbol("y", extended_real = FALSE); z <- Symbol("z"); is_extended_real(y)})), "False")
  expect_equal(.res(local({x <- Symbol("x", extended_real = TRUE); y <- Symbol("y", extended_real = FALSE); z <- Symbol("z"); is_extended_real(z)})), "None")
  expect_equal(.res(local({x <- Symbol("x", extended_real = TRUE); y <- Symbol("y", extended_real = FALSE); z <- Symbol("z"); is_extended_real(z, Q$extended_real(z))})), "True")
})

test_that("test_sathandlers matches SymPy", {
  tryCatch({.tup <- sym_symbols("x y z"); x <- .tup[[1]]; y <- .tup[[2]]; z <- .tup[[3]]}, error = function(e) NULL)
  expect_equal(.res(local({allargs(x, Q$zero(x), (x * y))})), "Q.zero(x) & Q.zero(y)")
  expect_equal(.res(local({allargs(x, (Q$positive(x) | Q$negative(x)), (x * y))})), "(Q.negative(x) | Q.positive(x)) & (Q.negative(y) | Q.positive(y))")
  expect_equal(.res(local({anyarg(x, Q$zero(x), (x * y))})), "Q.zero(x) | Q.zero(y)")
  expect_equal(.res(local({anyarg(x, (Q$positive(x) & Q$negative(x)), (x * y))})), "(Q.negative(x) & Q.positive(x)) | (Q.negative(y) & Q.positive(y))")
  expect_equal(.res(local({exactlyonearg(x, Q$zero(x), (x * y))})), "(Q.zero(x) & ~Q.zero(y)) | (Q.zero(y) & ~Q.zero(x))")
  expect_equal(.res(local({exactlyonearg(x, Q$zero(x), ((x * y) * z))})), "(Q.zero(x) & ~Q.zero(y) & ~Q.zero(z)) | (Q.zero(y) & ~Q.zero(x) & ~Q.zero(z)) | (Q.zero(z) & ~Q.zero(x) & ~Q.zero(y))")
  expect_equal(.res(local({exactlyonearg(x, (Q$positive(x) | Q$negative(x)), (x * y))})), "((Q.negative(x) | Q.positive(x)) & ~(Q.negative(y) | Q.positive(y))) | ((Q.negative(y) | Q.positive(y)) & ~(Q.negative(x) | Q.positive(x)))")
})
